// ============ PARSEN + DEDUPE ============
// Bereits gemeldete Anzeigen werden über Workflow-Static-Data gemerkt
// (Fingerprint aus Name+Preis+Fläche), damit die Mail nur NEUE Funde enthält.
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};

const zone = $('Zone für Zone').item.json.zone;
const body = $input.item.json;
const textBlocks = (body.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const clean = textBlocks.replace(/```json|```/g, '').trim();
const s = clean.indexOf('['), e = clean.lastIndexOf(']');

let finds = [];
if (s !== -1 && e !== -1) {
  try { finds = JSON.parse(clean.slice(s, e + 1)); } catch (err) { finds = []; }
}

const fresh = [];
for (const f of finds) {
  if (!f || !f.price || !f.size) continue;
  const fp = `${(f.name||'').toLowerCase().slice(0,40)}|${f.price}|${f.size}`;
  if (staticData.seen[fp]) continue;           // schon gemeldet
  staticData.seen[fp] = new Date().toISOString();
  fresh.push({
    ...f,
    zone,
    eur: Math.round(f.price / 655.957),
    ppm: Math.round(f.price / f.size),
    foundAt: new Date().toISOString().slice(0, 10)
  });
}

// Gedächtnis begrenzen (max ~500 Einträge)
const keys = Object.keys(staticData.seen);
if (keys.length > 500) keys.slice(0, keys.length - 500).forEach(k => delete staticData.seen[k]);

return fresh.map(f => ({ json: f }));
